pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ------------------------------------------------------------------
    // Basic ratios and progress
    // ------------------------------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let post_ratio = post_residual as f64 / bin_capacity as f64;
    let fill_ratio = 1.0 - residual_ratio;
    let dead_space = 1.0 - post_ratio;

    // ------------------------------------------------------------------
    // Base score: low post residual is good
    // ------------------------------------------------------------------
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // Excess post residual penalty – heavier early
    // ------------------------------------------------------------------
    let expected_post = (post_residual as i64 - item_size as i64).max(0) as u32;
    if expected_post as f64 > mean_residual {
        let excess = expected_post as f64 - mean_residual;
        let weight = 1.0 + 1.0 * (1.0 - progress);
        score += 5.0 * excess.powf(1.2) * weight;
    }

    // ------------------------------------------------------------------
    // Dead‑space penalty – quadratic, scaled by open bins
    // ------------------------------------------------------------------
    let dead_penalty = 3.5 * dead_space.powi(2);
    let dead_weight = 1.0 + 0.5 * (1.0 - progress);
    let open_weight = 1.0 + 0.06 * (open_bins_count as f64).ln();
    score -= dead_penalty * dead_weight * open_weight;

    // ------------------------------------------------------------------
    // Encourage residual close to global mean
    // ------------------------------------------------------------------
    if mean_residual > 1e-6 {
        let mean_diff = (post_residual as f64 - mean_residual).abs() / mean_residual;
        if mean_diff < 0.02 {
            score -= 3.0 * (0.02 - mean_diff);
        } else {
            score += 3.5 * mean_diff;
        }
    }

    // ------------------------------------------------------------------
    // Penalise excessive open bins (logarithmic)
    // ------------------------------------------------------------------
    score += 0.5 * (open_bins_count as f64 + 1.0).ln();

    // ------------------------------------------------------------------
    // Rarity bonus – few bins fit the item
    // ------------------------------------------------------------------
    let rarity = 1.0 / ((fitting_bins_count as f64 + 1.0).ln() + 1.8);
    score -= 5.8 * rarity;

    // ------------------------------------------------------------------
    // Look‑ahead for the next item
    // ------------------------------------------------------------------
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            score -= 3.5 * after_next as f64;
        } else {
            let slack = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 2.2 * slack.powi(3);
        }
    }

    // ------------------------------------------------------------------
    // Penalise bins that cannot fit the current item
    // ------------------------------------------------------------------
    if bin_residual > 0 && bin_residual < item_size {
        let slack = (item_size - bin_residual) as f64 / bin_capacity as f64;
        score += 5.5 * slack.powi(2);
    }

    // ------------------------------------------------------------------
    // New‑bin decision with dynamic threshold
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity {
        let new_bin_advantage = if next_item_size > 0 {
            (next_item_size as f64) / (bin_capacity as f64)
        } else {
            0.0
        };
        let new_bin_threshold = if open_bins_count < 5 { 0.4 } else { 0.28 };
        if new_bin_advantage > new_bin_threshold {
            score -= 7.0 * progress.powf(0.6);
        } else {
            score += 4.5 * progress.powf(1.3);
        }
    }

    // ------------------------------------------------------------------
    // Extreme fill ratio adjustments
    // ------------------------------------------------------------------
    if fill_ratio < 0.03 {
        score += 4.0;
    } else if fill_ratio > 0.98 {
        score -= 2.0;
    }

    // ------------------------------------------------------------------
    // Residual proximity to item size
    // ------------------------------------------------------------------
    let target_ratio = item_size as f64 / bin_capacity as f64;
    let diff = (residual_ratio - target_ratio).abs();
    if diff < 0.012 {
        score -= 1.8 * (0.012 - diff);
    }

    // ------------------------------------------------------------------
    // Reward bins where the post residual is almost zero
    // ------------------------------------------------------------------
    if post_residual < bin_capacity / 30 {
        score -= 1.8;
    }

    // ------------------------------------------------------------------
    // Additional bonus if post residual is close to next item size
    // ------------------------------------------------------------------
    if next_item_size > 0 {
        let diff_next = (post_residual as i32 - next_item_size as i32).abs() as i32;
        if diff_next <= 2 {
            score -= 1.2;
        }
    }

    // ------------------------------------------------------------------
    // Slight penalty if there are many fitting bins
    // ------------------------------------------------------------------
    if fitting_bins_count > 12 {
        score += 0.8;
    }

    // ------------------------------------------------------------------
    // Extra penalty for too many open bins
    // ------------------------------------------------------------------
    if open_bins_count > 22 {
        score += 0.7 * (open_bins_count as f64 - 22.0);
    }

    // ------------------------------------------------------------------
    // Additional compactness penalties
    // ------------------------------------------------------------------
    let mean_ratio = mean_residual / bin_capacity as f64;
    if residual_ratio > mean_ratio * 1.5 && open_bins_count > 15 {
        score += 1.6 * (residual_ratio - mean_ratio * 1.5).powi(2);
    }
    if residual_ratio < 0.05 && bin_residual > item_size {
        score += 2.2 * (0.05 - residual_ratio).powi(2);
    }

    score
