    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress through the stream
    let progress = step_index as f64 / total_items as f64;

    // Ratios for easier manipulation
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let post_residual_ratio = post_residual as f64 / bin_capacity as f64;
    let dead_space_ratio = 1.0 - post_residual_ratio;
    let fill_ratio = 1.0 - residual_ratio;

    // Base score: use the raw post‑residual
    let mut score = post_residual as f64;

    // Penalise bins whose post‑residual exceeds the global mean (non‑linear)
    let mean_gap = (post_residual as f64 - mean_residual).max(0.0);
    score -= 3.0 * mean_gap.powf(1.3);

    // Encourage tight packing by penalising dead space
    score -= 1.5 * dead_space_ratio.powi(2);

    // Early‑stream bias: tighter packing is more valuable early on
    let early_weight = (1.0 - progress).powf(2.5);
    score -= early_weight * (1.0 - dead_space_ratio).powi(2);

    // Penalise creating too many open bins (logarithmic growth)
    score += 0.35 * ((open_bins_count as f64 + 1.0).ln());

    // Rarity bonus: bins that are among the few that can fit get a lower score
    let rarity_factor = 1.0 / ((fitting_bins_count as f64 + 1.0).ln() + 1.0);
    score -= 5.0 * rarity_factor;

    // Look‑ahead for the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits – reward this choice
            let after_next = post_residual - next_item_size;
            score -= 2.0 * after_next as f64;
        } else {
            // Next item does not fit – penalise small leftover
            let slack = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 1.5 * slack.powi(3);
        }
    }

    // Extra penalty if the current bin cannot fit the item at all
    if bin_residual > 0 && bin_residual < item_size {
        let slack = (item_size - bin_residual) as f64 / bin_capacity as f64;
        score += 4.0 * slack.powi(2);
    }

    // New‑bin handling: weigh the benefit of opening a brand‑new bin
    if bin_residual == bin_capacity {
        // If the next item is a substantial fraction of capacity, open a new bin
        if next_item_size > 0
            && (next_item_size as f64) / (bin_capacity as f64) > 0.4
        {
            score -= 4.0 * progress.powf(0.7);
        } else {
            score += 6.0 * progress.powf(1.3);
        }
    }

    // Adjust for extremely low or high fill ratios
    if fill_ratio < 0.10 {
        score += 2.5;
    } else if fill_ratio > 0.95 {
        score -= 1.5;
    }

    // Coupling with the item size: reward bins whose residual is close to the item size
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let diff = (residual_ratio - item_ratio).abs();
    if diff < 0.05 {
        score -= 0.8 * (0.05 - diff);
    }

    score
}
